delete from public.antibiotic_interactions where drug_id = 'smx_tmp';
select (select count(*) from public.antibiotics where reviewed = false) as drafts, (select count(*) from public.antibiotic_interactions where reviewed = false) as interaction_drafts, (select count(*) from public.antibiotics where reviewed = true) as visible_to_visitors;
